 t=dict(id=id,title=title,range=[p],focus=[p],order=len(T)+1,lesson=lesson,group=group,questions=[question],answer=answer,explain=explain,points=points,hints=hints,guide='先读左边原文，再完成右边任务。',mode='objective',source='教师补充／优化旧题',role='学生独立',processing='定位、筛选与解释',accept='接受保留必要意义的等义表达；各意义点独立核对。',reject='遗漏题干限定或只写相关内容，却没有解释与题目之间的关系。',scoreGuide='课堂形成性检查。客观部分记录首次正确率，书面题按意思点由教师核对，不设全课百分制。',keywords=['观点','说明了什么','特别之处','如何','为什么','作用','哪些','举例说明'])
