task('p1-view','1 作者要说明什么',1,1,1,'作者在第一段提出了什么观点？','自古以来，多元而开放就是新加坡的重要特色。','第一句写许多游客的感受。第二句提出作者要在后文说明的观点，其中“自古以来”限定了时间。',['包括时间：自古以来','包括特色：多元而开放'],['注意“其实”后面的句子。','比较选项：有没有把古今的时间范围缩小？'],checks=[check('view','哪一项最准确地概括作者观点？',['现代新加坡凭多元美食吸引游客','古今新加坡都具有多元开放特色','古代新加坡主要依靠多元艺术发展','今日新加坡才逐步形成开放文化'],1,['只写现代和美食，范围太窄。','同时包含古今的时间范围与多元开放特色。','把说明范围缩为艺术，并加入原文没有的主因。','“才”与“自古以来”不符。'])],conceptNotes=[['观点','作者想说明的看法。后文的内容应与这个看法有关。']],role='师生共同完成')
task('p2-position','2a 地理位置的优势',2,1,2,'新加坡的地理位置有什么特别之处？','新加坡位于马来半岛南端，靠近马六甲海峡，是古代海上丝绸之路的一个中转站。','“得天独厚”是对地理条件的评价；作答要指出具体位置及其贸易作用。',['马来半岛南端','靠近马六甲海峡','古代海上丝绸之路中转站'],['回看“这个岛屿位于……”一句。','不要只重复“得天独厚”；找位置和作用。'],source='课本第2段旁注原题',evidence=[ev('加入说明位置及贸易作用的原句',2,['这个岛屿'],['马来半岛南端','马六甲海峡','中转站'])],checks=[check('position','原文怎样支持“得天独厚”这一评价？',['以游客赞誉突出文化对外的吸引力','以古钱发现突出考古研究的重要性','以不同族群突出今日文化的多样性','以具体位置说明它成为贸易中转站'],3,['游客评价在第1段，不能具体说明地理位置。','钱币支持早期贸易联系，不直接说明位置优势。','族群是后文内容，不能代替本段的位置依据。','具体位置与古代贸易作用共同说明优势。'])])
task('p2-coins','2b 古钱币能说明什么',2,1,2,'挖掘出的中国古代钱币证明了什么？','按课文的论述，出土的唐宋钱币说明，远在唐宋时期，新加坡就已参与海上贸易，为海上丝绸之路的发展做出了贡献。','先找“钱币”这一实物证据，再联系“由此可见”后的结论。它支持“自古以来”的时间范围；不能仅凭钱币断定当时的人口数量或所有文化。',['证据：唐宋时期的钱币','结论：很早参与海上贸易','联系“自古以来”'],['证据之后，作者用哪个词引出结论？','把“唐宋时期”和“海上丝绸之路”连起来解释。'],source='课本第2段旁注原题',role='教师完整示范后学生记录',mode='written',guide='点取证据与结论，再写一句解释。',evidence=[ev('连续加入“钱币”与“由此可见”的原句',2,['钱币'],['钱币','由此可见'])],fields=[dict(id='explain',label='这说明……',placeholder='说清时间和与外界的联系。')],conceptNotes=[['证据','课文用来支持看法的具体内容。'],['解释','说清这项内容与观点有什么联系。']],scoreGuide='教师核对：古代时间1点；参与海上贸易1点；与“自古以来”的联系1点。接受据课文推导的等义表达。')
events=['华人与当地人通婚，后代形成峇峇和娘惹','华人陆续到来，形成早期华人群体','不同区域的人汇集，族群逐渐多元化']
task('p3-timeline','3a 族群怎样逐渐多元',3,1,3,'新加坡的族群是如何变得越来越多元化的？先整理第三段的变化。','十四世纪开始，不同区域的人汇集；东南亚群岛居民成为最早的马来族群。十五世纪郑和下西洋后，华人陆续到来；部分华人与当地人通婚，其后代形成峇峇和娘惹。','按课文先后整理过程。王子命名的记载说明历史背景；本题更关注不同人群到来和交流。通婚发生在早期华人到来之后，原文没有给出明确年份。',['不同区域的人汇集','华人陆续到来','部分华人与当地人通婚'],['先找“十四世纪”“十五世纪”。','通婚及其后代应放在早期华人到来之后。'],source='课本第3—4段旁注原题，拆为随段步骤',fields=[select('first','先发生',events,events[2]),select('second','再发生',events,events[1]),select('third','随后出现',events,events[0])],oral=[['作者按时间顺序介绍，有什么作用？','呈现不同人群逐渐汇集的过程，说明多元特色有长期形成的历史。']])
task('p3-relation','3b 事例怎样支持观点',3,1,3,'第三段的具体事例怎样说明新加坡多元特色的形成？','不同区域的人陆续汇集，形成不同族群；部分人群还通过通婚发生联系，使族群逐渐多元。','“人多”只说数量。“多元”强调不同来源、不同族群；还要看他们怎样汇集、交流。',['分清人数多与族群多元','联系人群汇集与交流'],['比较“人数增加”和“来源不同”。','找出“来自不同区域”“通婚”所说明的联系。'],checks=[check('relation','哪一项解释最符合本段？',['各地人群汇集交流，族群逐渐多元','王子为小岛改名，多元族群随之形成','海上货物不断增加，族群因此完全相同','华人开始到来后，原有族群逐渐消失'],0,['来源不同的人汇集，并发生交流，符合本段。','命名不能单独证明族群形成。','把货物数量与族群特点混淆。','原文没有写原有族群消失。'])])
task('p4-open','4 开放的心胸',4,1,4,'新加坡的族群是如何变得越来越多元化的？结合第四段，完成解释。','莱佛士登陆后，更多华人、欧洲人和南印度的淡米尔人到来，各族群带来新特色，最终形成多元种族与文化。“海纳百川”在这里形容新加坡接纳不同族群和文化的宽广心胸。','先读第四段，再联系已读第三段。地方面积小与心胸宽广形成对照；“海纳百川”不指岛屿面积或河流数量。',['找全新到来的人群','说明各族带来新特色','解释接纳不同族群'],source='课本第3—4段旁注原题＋教参“海纳百川”理解',hints=['关注“更多的……”“每一个族群……”两处。','“海纳百川”在这里写的是态度，不是地理面积。'],evidence=[ev('加入族群到来及形成文化特色的原句',4,['莱佛士'],['华人','欧洲人','淡米尔人','新的特色'])],checks=[check('open','“海纳百川的心胸”在文中指什么？',['借海港的发展扩大岛屿的面积','以统一习惯减少各族群的差异','以开放态度接纳不同族群文化','靠人口增长吸引更多贸易货物'],2,['原文写心胸，不能按岛屿面积理解。','接纳差异并非取消差异。','本段写各族群带来新特色，体现开放包容。','人口和货物数量不能代替态度。'])],range=[3,4],focus=[4])
task('p5-link','5 第五段怎样连接上下文',5,2,5,'这一段有什么作用？','第五段起承上启下的过渡作用：第一句承接上文的海上贸易和多元种族；第二句引出下文从日常生活和文化艺术说明新加坡多元而开放的内容。','分别指出上文内容和下文方向。“承上启下”是作用名称，具体内容才显示你读懂了。',['承上：贸易与多元种族','启下：日常生活与文化艺术','写清过渡作用'],['先看第一句在回顾哪些已经读过的内容。','第二句提出的两个方面，将在第六段展开。'],source='课本第5段旁注原题',role='师生共同完成后学生独立组织',mode='written',guide='先看简短示例，再取两句原文，完成解释。',conceptNotes=[['过渡段（transition）','连接前后的段落。'],['小示例','前文写交通，后文写饮食：“交通方便，饮食也丰富。”前半回顾交通，后半带出饮食。']],evidence=[ev('加入本段两句原文',5,['海上贸易'],['海上贸易','日常生活','文化艺术'])],fields=[dict(id='function',label='这一段的作用是……',placeholder='承接上文的什么？引出下文的什么？')],scoreGuide='作用名称1点；承上内容1点；启下内容1点。三个意义点独立核对，仅写术语不算完整分析。')
task('p6-food','6a 饮食中的多元',6,2,6,'这一段中提到了饮食方面的哪些体验？','喝的方面有中国茶、奶茶和咖啡；吃的方面有鸡饭、椰浆饭和黄姜饭。不同饮食在这里并存，使人感受到多元文化。','先分类找全信息，再解释其意义。香料、瓷器、丝绸、茶叶在段首属于贸易货物，不能都当成饮食体验。',['饮品三项','食物三项','说明不同饮食并存'],['找到“想喝点什么”“想吃点什么”。','把喝的与吃的分开，不要混入瓷器和丝绸。'],source='课本第6段旁注原题',fields=[select('drinks','喝的体验',['中国茶、奶茶、咖啡','香料、茶叶、丝绸','中国茶、咖啡、黄姜饭'],'中国茶、奶茶、咖啡'),select('food','吃的体验',['鸡饭、椰浆饭、中国茶','鸡饭、椰浆饭、黄姜饭','香料、瓷器、黄姜饭'],'鸡饭、椰浆饭、黄姜饭')],checks=[check('food-meaning','这些饮食事例主要说明什么？',['游客口味决定各种食物的优劣','不同饮食并存，体现文化多元','各种食物都来自同一个地区','饮食种类增多，使传统逐渐消失'],1,['原文没有比较优劣。','具体饮食种类说明文化多样。','同一来源与本段所写不符。','原文强调并存，并未写传统消失。'])])
arts=['华族','马来族','印度族']
task('p6-art','6b 艺术中的传承与创新',6,2,6,'新加坡的多元开放在文化艺术方面有哪些表现？','华族有传统南音和富有时代特色的新谣；马来族有班顿诗；印度族有婆罗多舞。这些不同形式并存，体现文化多元；传统南音与富有时代特色的新谣，也让我们看到传承与创新。','分类是第一步，还要说明事例与观点的关系。不能只回答“艺术很多”或“艺术水平高”。',['艺术形式对应族群','不同形式并存体现多元','南音与新谣体现传承和创新'],['回看“这里有华族传统的南音……”一句。','“传统”与“时代特色”分别提醒你什么？'],source='课本第6段旁注原题＋教参引导',fields=[select('nanyin','南音、新谣',arts,'华族'),select('pantun','班顿诗',arts,'马来族'),select('dance','婆罗多舞',arts,'印度族')],checks=[check('inherit','南音和新谣放在一起，突出什么？',['新艺术逐渐取代旧艺术的位置','传统艺术比现代艺术更受欢迎','华族艺术比其他族群更有价值','传统与时代特色可以同时存在'],3,['文中写并存，没有写取代。','没有比较受欢迎程度。','没有进行族群艺术的价值排名。','传统与时代特色分别呼应传承和创新。'])],conceptNotes=[['传承','把已有的文化接续下来。'],['创新','在发展中形成新的内容或形式。']],oral=[['为什么饮食与艺术都写？','从不同方面展示多元开放在日常生活中的具体表现，使观点有更充分的内容支持。']])
task('p7-ending','7 变与不变',7,2,7,'新加坡应该如何继续保持“多元而开放”的特色？','继续兼容并蓄，求同存异，共同开创未来。第七段“始终未变”呼应第一段“自古以来”，强调多元开放特色延续至今。','先理解变化中的不变，再把“求同存异”放进相处情境：寻找共同点，同时尊重和保留差异。',['兼容并蓄、求同存异','始终未变呼应自古以来'],['看“尽管……但……”后的重点。','结尾既总结特色，也提出继续保持特色的做法。'],source='教参第7段原题＋教师补充',checks=[check('ending','结尾强调的“不变”是什么？',['多元而开放的特色一直延续','城市外貌与过去保持完全相同','各族饮食习惯从未发生任何变化','世界环境一直维持原来的状态'],0,['“特色始终未变”明确回应题意。','世事变迁，不代表城市外貌不变。','不能把特色延续扩大为所有习惯不变。','原文明确说世事不断变迁。']),check('coexist','哪种做法更符合“求同存异”？',['为统一活动，要求各族放弃原有习俗','为避免争论，让各族始终各自活动','为共同合作，讨论目标并尊重习俗','为方便管理，只采用人数最多者习俗'],2,['把统一误解为取消差异。','保留差异不能省掉寻找共同点。','共同目标体现求同，尊重习俗体现存异。','只采用多数者习俗没有体现尊重差异。'])],conceptNotes=[['首尾呼应（ending echoes the opening）','结尾回应开头的意思，使全文联系更紧密。']])
struct=['提出自古以来多元开放的重要特色','说明地理位置及古代贸易联系','说明不同族群汇集形成多元文化','从日常生活与文化艺术展开说明','总结特色延续，并提出未来期望']
task('whole-structure','8 全文结构与意义段',1,2,8,'除了第三和第四自然段组成的意义段，课文中还可以划分出哪些意义段？完成课本结构表。','可再分为第1段、第2段、第5—6段和第7段。全文为：第1段提出观点；第2段说明地理与贸易；第3—4段说明族群形成；第5—6段说明日常生活与文化艺术；第7段总结并展望。','意义段按内容划分，可以只有一个自然段，也可以包含几个相邻自然段。第5段虽起过渡作用，仍可与第6段共同构成日常生活和文化艺术的意义段。',['按内容分意义段','第5段作用与第5—6段内容分组不冲突','结构与观点对应'],['先找各部分主要写什么。','第5段引出生活与艺术，第6段接着具体展开。'],source='课本《预习》意义段题＋《阅读放大镜》二结构表',scope='full',range=[1,7],focus=[1],conceptNotes=[['自然段','按书写形式分段。'],['意义段','按内容归组；可包括一个或几个相邻自然段。']],fields=[select('s1','第1段',struct,struct[0]),select('s2','第2段',struct,struct[1]),select('s34','第3—4段',struct,struct[2]),select('s56','第5—6段',struct,struct[3]),select('s7','第7段',struct,struct[4])])
bank=['海峡','聚集','海纳百川','初来乍到']
task('words-prep','9a 课本词语核对',2,3,9,'根据解释从课文中找出词语，并用方框圈出来。','1 海峡；2 聚集；3 海纳百川；4 初来乍到。','结合题目注明的段落，找到与解释相符的词语。四项合并核对一次，不再另做同样的词义测验。',['解释与词语对应','按指定段落定位'],['第一项看第2段，第二项看第3段。','第三项看第4段，第四项看第6段。'],source='课本《预习》第一题原题',scope='full',range=[1,7],focus=[2],bank=bank,blanks=[dict(id='v1',before='两块陆地之间连接两个海洋的狭窄水道（第2段）：',after='',answer=bank[0]),dict(id='v2',before='聚集（第3段）：',after='',answer='汇集'),dict(id='v3',before='形容胸怀宽广，能包容一切（第4段）：',after='',answer=bank[2]),dict(id='v4',before='初次来到某个地方（第6段）：',after='',answer=bank[3])])
